import {readFileSync} from 'node:fs'
const manifest=JSON.parse(readFileSync(new URL('../../../docs/customer-account-b7-execution-manifest-v2.json',import.meta.url)))
export function b7Inputs(){return manifest.orders.map((o,i)=>{const c=manifest.contactFixtures[o.actor==='guest'?'G':o.actor];return {action:'create-cake',...(o.expectedOwnerUid?{customerAccount:'link'}:{}),data:{contractVersion:'au-renewal.2026-10.v2',requestId:o.requestId||`b700000${i+1}-0000-4000-8000-000000000001`,customerName:c.name,customerPhone:c.phone,customerEmail:c.email,pickupDate:o.pickupDate,pickupTime:o.pickupTime,privacyConsent:true,website:'',requestNote:'',promoCode:o.couponFixture==='manual'?'JENNIETEST7':o.couponFixture==='review'?'FOXKIWI7Q2MK':'',orderLines:[{lineId:`line-${i}`,offerId:o.productId,quantity:1,...o.lineOptions}]}}})}
